<template><view v-if="sourceId" class="sheet-overlay" @tap.self="$emit('close')"><view class="source-sheet"><view class="sheet-header"><text class="eyebrow">史料为据 / SOURCE</text><button class="round-button" aria-label="关闭来源" @tap="$emit('close')">×</button></view><scroll-view scroll-y class="sheet-scroll"><StatePanel v-if="loading||error" :loading="loading" :error="error" @retry="load"/><template v-else-if="source"><text class="tag">{{source.access_status}}</text><text class="source-title">{{source.title}}</text><text class="muted">{{source.publisher}}</text><view class="source-quote"><text class="eyebrow">引用定位</text><text>{{source.location||'定位整理中'}}</text></view><view class="source-boundary"><text class="block-title">这份资料能说明什么</text><text>{{source.boundary||'支持范围整理中'}}</text></view><view v-for="f in source.facts" :key="f.id" class="fact-item"><text class="fact-status">{{f.review_status==='attributed'?'来源归因记载':'已核来源记载'}}</text><text>{{f.text}}</text><text class="small">{{f.location}} · {{f.id}}</text></view><view class="source-meta"><text>作者：{{source.author||'未显示'}}</text><text>发布日期：{{source.published_at||'未显示'}}</text><text>访问日期：{{source.checked_at||'未显示'}}</text><text>媒体许可：{{source.media_permission||'未核'}}</text><text>转载关系：{{source.reprint_note||'未显示'}}</text><text class="url-text">原始网址：{{source.original_url}}</text></view><button class="primary" @tap="copy">复制来源网址</button><text class="copy-note">可在浏览器中核对原始来源。</text></template></scroll-view></view></view></template>
<script setup>
import {ref,watch} from 'vue';import {api} from '../lib/api.js';import StatePanel from './StatePanel.vue'
const props=defineProps({sourceId:String});defineEmits(['close']);const source=ref(null),loading=ref(false),error=ref('');let seq=0
async function load(){const token=++seq;loading.value=true;error.value='';try{const data=await api('sources/'+props.sourceId);if(token===seq)source.value=data}catch(e){if(token===seq)error.value=e.message}finally{if(token===seq)loading.value=false}}
watch(()=>props.sourceId,id=>{if(id)load();else{seq++;source.value=null}})
function copy(){uni.setClipboardData({data:source.value.original_url,success:()=>uni.showToast({title:'来源网址已复制',icon:'none'})})}
</script>
